// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Job status, stage, token usage, proposal, dry-run traces, problems and diff
	// (GET /ai/jobs/{jobId})
	GetAIJob(ctx context.Context, request GetAIJobRequestObject) (GetAIJobResponseObject, error)
	// Save the proposal as a new scenario or a new scenario version
	// (POST /ai/jobs/{jobId}/approve)
	ApproveAIJob(ctx context.Context, request ApproveAIJobRequestObject) (ApproveAIJobResponseObject, error)
	// AI providers configured for the organisation (keys are never returned)
	// (GET /ai/providers)
	ListAIProviders(ctx context.Context, request ListAIProvidersRequestObject) (ListAIProvidersResponseObject, error)
	// Create or replace an AI provider by name
	// (POST /ai/providers)
	PutAIProvider(ctx context.Context, request PutAIProviderRequestObject) (PutAIProviderResponseObject, error)

	// (DELETE /ai/providers/{providerId})
	DeleteAIProvider(ctx context.Context, request DeleteAIProviderRequestObject) (DeleteAIProviderResponseObject, error)

	// (GET /audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)

	// (POST /auth/login)
	Login(ctx context.Context, request LoginRequestObject) (LoginResponseObject, error)

	// (POST /auth/logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)

	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)

	// (PUT /me/password)
	ChangePassword(ctx context.Context, request ChangePasswordRequestObject) (ChangePasswordResponseObject, error)

	// (GET /projects)
	ListProjects(ctx context.Context, request ListProjectsRequestObject) (ListProjectsResponseObject, error)

	// (POST /projects)
	CreateProject(ctx context.Context, request CreateProjectRequestObject) (CreateProjectResponseObject, error)

	// (DELETE /projects/{projectId})
	DeleteProject(ctx context.Context, request DeleteProjectRequestObject) (DeleteProjectResponseObject, error)

	// (GET /projects/{projectId})
	GetProject(ctx context.Context, request GetProjectRequestObject) (GetProjectResponseObject, error)

	// (PATCH /projects/{projectId})
	UpdateProject(ctx context.Context, request UpdateProjectRequestObject) (UpdateProjectResponseObject, error)

	// (GET /projects/{projectId}/ai/jobs)
	ListAIJobs(ctx context.Context, request ListAIJobsRequestObject) (ListAIJobsResponseObject, error)
	// Generate a scenario with an AI model (asynchronous)
	// (POST /projects/{projectId}/ai/jobs)
	CreateAIJob(ctx context.Context, request CreateAIJobRequestObject) (CreateAIJobResponseObject, error)

	// (GET /projects/{projectId}/runs)
	ListRuns(ctx context.Context, request ListRunsRequestObject) (ListRunsResponseObject, error)

	// (POST /projects/{projectId}/runs)
	CreateRun(ctx context.Context, request CreateRunRequestObject) (CreateRunResponseObject, error)

	// (GET /projects/{projectId}/scenarios)
	ListScenarios(ctx context.Context, request ListScenariosRequestObject) (ListScenariosResponseObject, error)

	// (POST /projects/{projectId}/scenarios)
	CreateScenario(ctx context.Context, request CreateScenarioRequestObject) (CreateScenarioResponseObject, error)

	// (GET /projects/{projectId}/secrets)
	ListSecrets(ctx context.Context, request ListSecretsRequestObject) (ListSecretsResponseObject, error)

	// (PUT /projects/{projectId}/secrets)
	PutSecret(ctx context.Context, request PutSecretRequestObject) (PutSecretResponseObject, error)

	// (DELETE /projects/{projectId}/secrets/{name})
	DeleteSecret(ctx context.Context, request DeleteSecretRequestObject) (DeleteSecretResponseObject, error)

	// (GET /projects/{projectId}/targets)
	ListTargets(ctx context.Context, request ListTargetsRequestObject) (ListTargetsResponseObject, error)

	// (POST /projects/{projectId}/targets)
	CreateTarget(ctx context.Context, request CreateTargetRequestObject) (CreateTargetResponseObject, error)
	// Kill switch for every active run in the organisation
	// (POST /runs/kill-all)
	KillAllRuns(ctx context.Context, request KillAllRunsRequestObject) (KillAllRunsResponseObject, error)

	// (GET /runs/{runId})
	GetRun(ctx context.Context, request GetRunRequestObject) (GetRunResponseObject, error)
	// Kill switch for one run; all load stops immediately
	// (POST /runs/{runId}/kill)
	KillRun(ctx context.Context, request KillRunRequestObject) (KillRunResponseObject, error)
	// Live metrics as server-sent events
	// (GET /runs/{runId}/live)
	StreamRun(ctx context.Context, request StreamRunRequestObject) (StreamRunResponseObject, error)

	// (GET /runs/{runId}/report)
	GetRunReport(ctx context.Context, request GetRunReportRequestObject) (GetRunReportResponseObject, error)
	// Stop gracefully; in-flight iterations may finish
	// (POST /runs/{runId}/stop)
	StopRun(ctx context.Context, request StopRunRequestObject) (StopRunResponseObject, error)

	// (GET /runs/{runId}/timeline)
	GetRunTimeline(ctx context.Context, request GetRunTimelineRequestObject) (GetRunTimelineResponseObject, error)

	// (POST /scenarios/validate)
	ValidateScenario(ctx context.Context, request ValidateScenarioRequestObject) (ValidateScenarioResponseObject, error)

	// (DELETE /scenarios/{scenarioId})
	DeleteScenario(ctx context.Context, request DeleteScenarioRequestObject) (DeleteScenarioResponseObject, error)

	// (GET /scenarios/{scenarioId})
	GetScenario(ctx context.Context, request GetScenarioRequestObject) (GetScenarioResponseObject, error)

	// (GET /scenarios/{scenarioId}/versions)
	ListScenarioVersions(ctx context.Context, request ListScenarioVersionsRequestObject) (ListScenarioVersionsResponseObject, error)

	// (POST /scenarios/{scenarioId}/versions)
	CreateScenarioVersion(ctx context.Context, request CreateScenarioVersionRequestObject) (CreateScenarioVersionResponseObject, error)

	// (GET /scenarios/{scenarioId}/versions/{version})
	GetScenarioVersion(ctx context.Context, request GetScenarioVersionRequestObject) (GetScenarioVersionResponseObject, error)
	// Create the first organisation and owner account
	// (POST /setup)
	Setup(ctx context.Context, request SetupRequestObject) (SetupResponseObject, error)

	// (DELETE /targets/{targetId})
	DeleteTarget(ctx context.Context, request DeleteTargetRequestObject) (DeleteTargetResponseObject, error)

	// (GET /targets/{targetId})
	GetTarget(ctx context.Context, request GetTargetRequestObject) (GetTargetResponseObject, error)

	// (PATCH /targets/{targetId})
	UpdateTarget(ctx context.Context, request UpdateTargetRequestObject) (UpdateTargetResponseObject, error)
	// Check the ownership token for a public target
	// (POST /targets/{targetId}/verify)
	VerifyTarget(ctx context.Context, request VerifyTargetRequestObject) (VerifyTargetResponseObject, error)

	// (GET /tokens)
	ListTokens(ctx context.Context, request ListTokensRequestObject) (ListTokensResponseObject, error)

	// (POST /tokens)
	CreateToken(ctx context.Context, request CreateTokenRequestObject) (CreateTokenResponseObject, error)

	// (DELETE /tokens/{tokenId})
	DeleteToken(ctx context.Context, request DeleteTokenRequestObject) (DeleteTokenResponseObject, error)

	// (GET /users)
	ListUsers(ctx context.Context, request ListUsersRequestObject) (ListUsersResponseObject, error)

	// (POST /users)
	CreateUser(ctx context.Context, request CreateUserRequestObject) (CreateUserResponseObject, error)

	// (DELETE /users/{userId})
	DeleteUser(ctx context.Context, request DeleteUserRequestObject) (DeleteUserResponseObject, error)

	// (PATCH /users/{userId})
	UpdateUser(ctx context.Context, request UpdateUserRequestObject) (UpdateUserResponseObject, error)

	// (GET /version)
	GetVersion(ctx context.Context, request GetVersionRequestObject) (GetVersionResponseObject, error)

	// (GET /workers)
	ListWorkers(ctx context.Context, request ListWorkersRequestObject) (ListWorkersResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// GetAIJob operation middleware
func (sh *strictHandler) GetAIJob(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID) {
	var request GetAIJobRequestObject

	request.JobId = jobId

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.GetAIJob(ctx, request.(GetAIJobRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "GetAIJob")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(GetAIJobResponseObject); ok {
		if err := validResponse.VisitGetAIJobResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

